assert len(VIDEO_PROMPTS) == 200, f"Need 200 video prompts, got {len(VIDEO_PROMPTS)}"

# ── Progress tracking ─────────────────────────────────────────────────────────
def load_progress():
    if PROGRESS_FILE.exists():
        return json.loads(PROGRESS_FILE.read_text())
    return {"photos_done": [], "videos_done": []}

def save_progress(p):
    PROGRESS_FILE.write_text(json.dumps(p, indent=2))

# ── Photo generation ──────────────────────────────────────────────────────────
def generate_photo(idx):
    out = OUT_DIR / f"photo_{idx:03d}.webp"
    if out.exists() and out.stat().st_size > 10000:
        return idx, True, "cached"
    prompt = PHOTO_PROMPTS[idx - 1]
    try:
        r = requests.post(
            f"{PIXEL_URL}/api/v1/image/create",
            headers={"X-API-Key": PIXEL_KEY, "Content-Type": "application/json"},
            json={"prompt": prompt, "aspect_ratio": "16:9"},
            timeout=120
        )
        if r.status_code != 200:
            return idx, False, f"HTTP {r.status_code}"
        data = r.json()
        img_b64 = data.get("image_b64", "")
        if not img_b64:
            return idx, False, "no image_b64"
        out.write_bytes(base64.b64decode(img_b64))
        return idx, True, f"{out.stat().st_size // 1024}KB"
    except Exception as e:
        return idx, False, str(e)[:80]

def generate_all_photos():
    prog = load_progress()
    done = set(prog["photos_done"])
    todo = [i for i in range(1, 201) if i not in done]
    print(f"[Photos] Всего: 200 | Готово: {len(done)} | Осталось: {len(todo)}", flush=True)
    if not todo:
        print("[Photos] Все фото готовы!", flush=True)
        return
    with ThreadPoolExecutor(max_workers=5) as ex:
        futures = {ex.submit(generate_photo, i): i for i in todo}
        for fut in as_completed(futures):
            idx, ok, msg = fut.result()
            if ok:
                prog = load_progress()
                prog["photos_done"].append(idx)
                save_progress(prog)
                print(f"  [Photo {idx:03d}] OK {msg}", flush=True)
            else:
                print(f"  [Photo {idx:03d}] FAIL: {msg}", flush=True)

# ── Video generation via Grok ─────────────────────────────────────────────────
def generate_all_videos():
    sys.path.insert(0, str(BASE / 'agents/media_generator'))
    os.chdir(str(BASE / 'agents/media_generator'))
    from grok_agent import generate_grok_video
    from utils import PLATFORMS

    prog = load_progress()
    done_set = set(prog["videos_done"])

    photos = [OUT_DIR / f"photo_{i:03d}.webp" for i in range(1, 201)]
    prompts = VIDEO_PROMPTS

    available = [(i+1, p, prompts[i]) for i, p in enumerate(photos) if p.exists()]
    todo = [(i, p, pr) for i, p, pr in available if i not in done_set]
    print(f"[Videos] Фото готово: {len(available)} | Видео готово: {len(done_set)} | Осталось: {len(todo)}", flush=True)

    if not todo:
        print("[Videos] Все видео готовы!", flush=True)
        return

    ph_list = [p for _, p, _ in todo]
    pr_list = [pr for _, _, pr in todo]

    platform = PLATFORMS["2"].copy()
    platform["key"] = "2"

    video_out = OUT_DIR / "videos"
    video_out.mkdir(exist_ok=True)

    result = generate_grok_video(
        platform=platform,
        photos=ph_list,
        prompts=pr_list,
        out_dir=video_out,
        session="religion_200",
        num_tabs=3,
    )
    print(f"[Videos] Готово: {result}", flush=True)

# ── Cleanup after generation ──────────────────────────────────────────────────
def cleanup():
    import glob as _glob
    # Delete all photos
    for f in _glob.glob(str(OUT_DIR / "photo_*.webp")):
        os.remove(f)
    print(f"[Cleanup] Фото удалены", flush=True)
    # Delete local progress file
    if PROGRESS_FILE.exists():
        PROGRESS_FILE.unlink()
    print(f"[Cleanup] _progress.json удалён", flush=True)
    # Delete grok_progress.json
    grok_prog = BASE / "temp" / "grok_progress.json"
    if grok_prog.exists():
        grok_prog.unlink()
    print(f"[Cleanup] grok_progress.json удалён", flush=True)


# ── Main ──────────────────────────────────────────────────────────────────────
if __name__ == "__main__":
    print("=" * 60, flush=True)
    print("ГЕНЕРАЦИЯ 200 ФУТАЖЕЙ — RELIGION ES (v2 — God speaks)", flush=True)
    print("=" * 60, flush=True)
    print("[STEP 1] Генерация фото...", flush=True)
    generate_all_photos()
    print("\n[STEP 2] Генерация видео в Grok (3 таба)...", flush=True)
    generate_all_videos()
    print("\n[STEP 3] Cleanup...", flush=True)
    cleanup()
    print("\nГОТОВО!", flush=True)
